class Solution { public int[] findOrder(int n,int[][] p) { List<Integer>[] g=new List[n];for(int i=0;i<n;i++)g[i]=new ArrayList<>();int[] d=new int[n];for(int[] e:p){g[e[1]].add(e[0]);d[e[0]]++;}PriorityQueue<Integer> q=new PriorityQueue<>();for(int i=0;i<n;i++)if(d[i]==0)q.add(i);int[] out=new int[n];int k=0;while(!q.isEmpty()){int u=q.remove();out[k++]=u;for(int v:g[u])if(--d[v]==0)q.add(v);}return k==n?out:new int[0];} }
